    ["Positions class bar ABOVE Essential Cooldowns"] = "Позиции классовой панели НАД основными кулдаунами",
    ["Preserve HP color on all unit frames"] = "Сохраните цвет HP на всех кадрах устройства.",
    ["Press Ctrl+C to copy:"] = "Нажмите Ctrl+C, чтобы скопировать:",
    ["Preview follows the current castbar visibility, icon, text, and global color settings."] = "Предварительный просмотр соответствует текущей видимости панели приведения, значку, тексту и глобальным настройкам цвета.",
    ["Profile actions"] = "Действия профиля",
    ["Quick Setup: Detached Class Bar"] = "Быстрая настройка: отдельная панель классов",
    ["Reload"] = "Перезагрузить",
    ["Rows"] = "Строки",
    ["Same setting as each unit page > Transparency. It uses this same HP track color; off here means at least one unit frame is off."] = "Те же настройки, что и на каждой странице модуля > Прозрачность. Он использует тот же цвет дорожки HP; Off здесь означает, что по крайней мере один единичный кадр отключен.",
    ["Secret aura (name/fingerprint matched)"] = "Секретная аура (имя /fingerprint соответствует)",
    ["Select:"] = "Выберите:",
    ["Set Bar Background Tint to white and enable Custom color in Dark Mode. If black, enable Preserve HP color on all unit frames."] = "Установите для параметра «Оттенок фона панели» белый цвет и включите «Пользовательский цвет» в темном режиме. Если черный, включите «Сохранить цвет HP на всех кадрах объекта».",
    ["Setup Now"] = "Настроить сейчас",
    ["Slot"] = "Слот",
    ["Some layout changes rebuild frames, while visual changes apply instantly. If needed, close and reopen the menu or reload after large profile/import changes."] = "Некоторые изменения макета перестраивают кадры, а визуальные изменения применяются мгновенно. При необходимости закройте и снова откройте меню или перезагрузите компьютер после больших изменений профиля /import.",
    ["Syncs & anchors power bar to class resources"] = "Синхронизирует и привязывает панель мощности к ресурсам класса.",
    ["The active profile is saved per character. New characters start on this profile instead of Default."] = "Активный профиль сохраняется отдельно для каждого персонажа. Новые персонажи начинают с этого профиля вместо Default.",
    ["This layer is off in settings and cannot be shown in preview."] = "Этот слой отключен в настройках и не может быть отображен при предварительном просмотре.",
    ["Type a name here before creating or copying a profile."] = "Введите здесь имя перед созданием или копированием профиля.",
    ["Undo"] = "Отменить",
    ["Unit Frame Preview"] = "Предварительный просмотр кадра устройства",
    ["Unit frame status icons are on each unit page. Group frame indicators are in Group Frames > Indicators."] = "Значки состояния блока находятся на каждой странице объекта. Индикаторы групповых рамок находятся в разделе «Групповые рамки» > «Индикаторы».",
    ["Use /msuf to open MSUF2. The Dashboard also contains reset, support, profile, and scale tools."] = "Используйте /msuf, чтобы открыть MSUF2. Панель мониторинга также содержит инструменты сброса, поддержки, профиля и масштабирования.",
    ["Use Dashboard > Reset Positions for frame movers. Use Profiles only when you want to reset, copy, import, or replace profile data."] = "Используйте «Панель мониторинга» > «Сбросить позиции» для перемещения кадров. Используйте профили только в том случае, если вы хотите сбросить, скопировать, импортировать или заменить данные профиля.",
    ["Use Global Style > Bars for highlight borders and Group Frames > Indicators for role, threat, dispel, spell, corner, and raid-marker indicators."] = "Используйте «Глобальный стиль» > «Полосы» для выделения границ и «Групповые рамки» > «Индикаторы» для индикаторов роли, угрозы, рассеивания, заклинания, угла и маркера рейда.",
    ["Use Group Frames > Layout for size and spacing, Buffs & Debuffs for aura clutter, and Indicators for fixed-position status icons."] = "Используйте «Групповые рамки» > «Макет» для размера и интервала, «Усиления и ослабления» для устранения беспорядка в ауре и «Индикаторы» для фиксированных значков состояния.",
    ["Use Group Frames pages: Layout for size/growth/sorting, Health & Text for bars/text, Buffs & Debuffs for auras, and Indicators for status icons."] = "Используйте страницы групповых фреймов: макет для размера /growth/sorting, здоровье и текст для полосок /text, усиления и ослабления для аур и индикаторы для значков статуса.",
    ["Use MSUF Edit Mode to drag a single unit frame. Use the unit page > Anchoring when you need exact anchor targets or X/Y values."] = "Используйте режим редактирования MSUF, чтобы перетащить отдельный кадр. Используйте страницу модуля > Привязка, если вам нужны точные цели привязки или значения X/Y.",
    ["Use MSUF Edit Mode to drag supported castbars. Per-unit castbar enable/icon/text options are on each unit page; shared castbar style is in Global Style > Castbar."] = "Используйте режим редактирования MSUF для перетаскивания поддерживаемых панелей приведения. Параметры включения панели приведения для каждого устройства/icon/text находятся на каждой странице устройства; Общий стиль панели приведения находится в разделе «Глобальный стиль» > «Панель приведения».",
    ["Use MSUF Edit Mode to drag the player frame. For exact anchor or X/Y values, open Player > Anchoring after that."] = "Используйте режим редактирования MSUF, чтобы перетащить рамку проигрывателя. Чтобы получить точные значения привязки или X/Y, после этого откройте Player > Anchoring.",
    ["Use the Dashboard scale controls for menu scale or UI scale. You can also resize the MSUF2 window from its corner."] = "Используйте элементы управления масштабом информационной панели для масштабирования меню или масштаба UI. Вы также можете изменить размер окна MSUF2 от его угла.",
    ["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, GCD, text, and interrupt options."] = "Используйте страницу юнита для переключения панели приведения для каждого юнита и раздел «Глобальный стиль» > «Панель приведения» для общих текстур, направления, GCD, текста и параметров прерывания.",
    ["Use this if HP Bar fade makes the empty health area disappear or look black. It keeps the same HP track color from Colors."] = "Используйте это, если при затухании полосы HP пустая область здоровья исчезает или выглядит черной. Он сохраняет тот же цвет дорожки HP из Colors.",
    ["Value:"] = "Значение:",
    ["View"] = "Посмотреть",
    ["Welcome to Class Resources!"] = "Добро пожаловать на ресурсы класса!",
    ["WoW blocks some protected frame changes in combat. Leave combat, then apply layout, anchoring, enable/disable, profile, or protected-frame changes."] = "WoW блокирует некоторые защищенные изменения кадров в бою. Выйдите из боя, затем примените изменения макета, привязки, включения /disable, профиля или защищенного фрейма.",
    ["bottom"] = "дно",
    ["change background color unit frames"] = "изменить цвет фона фреймов юнитов",
    ["class-resource layout, behavior, style, auto-hide, detached power bar and alternative mana settings"] = "Расположение ресурсов класса, поведение, стиль, автоматическое скрытие, отдельная панель мощности и альтернативные настройки маны",
    ["click layers to hide - drag preview elements - arrows nudge selected"] = "щелкните слои, чтобы скрыть - перетащите элементы предварительного просмотра - стрелки сдвинут выбранные",
    ["frame colors, class/NPC colors, power colors, castbar colors, aura colors and gameplay color settings"] = "цвета рамки, цвета class/NPC, цвета мощности, цвета панели каста, цвета ауры и настройки цвета игрового процесса.",
    ["gameplay enhancement settings such as combat text, crosshair and click-cast behavior"] = "настройки улучшения игрового процесса, такие как боевой текст, прицел и поведение при нажатии",
    ["gf_layout"] = "gf_layout",
