    ["language/menu behavior, update pacing, tooltips, Blizzard-frame handling, minimap icon, sounds and range-fade settings"] = "Поведение языка/menu, скорость обновления, всплывающие подсказки, обработка кадров Blizzard, значок на мини-карте, звуки и настройки затухания диапазона",
    ["none"] = "нет",
    ["optional style/module settings such as MSUF Style and dropdown style"] = "дополнительные настройки стиля /module, такие как стиль MSUF и стиль раскрывающегося списка.",
    ["scope disabled"] = "область действия отключена",
