L["|cffffd700MSUF:|r Preserve HP color uses the same HP track color from Colors, but some bar textures may look different."] = "|cffffd700MSUF:|r Сохранение цвета HP использует тот же цвет дорожки HP из раздела цветов, но некоторые текстуры полос могут выглядеть иначе."
L["Click a handle to select - drag custom layers - arrow keys nudge selected; Blizzard is locked"] = "Щелкните маркер для выбора - перетаскивайте пользовательские слои - стрелки сдвигают выбранное; Blizzard заблокирован"
