L["Delete profile '%s'?\n\nThis removes the selected profile from MSUF. Other profiles are not affected, but this profile cannot be restored unless you exported or copied it first."] = "Удалить профиль '%s'?\n\nЭто удалит выбранный профиль из MSUF. Другие профили не будут затронуты, но этот профиль нельзя будет восстановить, если вы заранее не экспортировали или не скопировали его."
L["Discard all changes and exit?"] = "Отменить все изменения и выйти?"
