L["When enabled, WoW owns debuff icons. MSUF hide categories and custom debuff positioning do not filter Blizzard-rendered debuffs."] = "Если включено, WoW управляет значками дебаффов. Категории скрытия MSUF и пользовательское позиционирование дебаффов не фильтруют дебаффы, отрисованные Blizzard."
L["When enabled, WoW owns defensive icons. MSUF custom positioning and styling apply only when this is off or the renderer is MSUF Custom."] = "Если включено, WoW управляет защитными значками. Пользовательское позиционирование и стиль MSUF применяются только когда это отключено или выбран рендерер MSUF Custom."
