L["Keep tanks and manually pinned group members in one stable strip without removing them from the normal Party or Raid frames."]="Держите танков и вручную закреплённых участников в одной постоянной полосе, не убирая их из обычных рамок группы или рейда."
L["Profile-wide layout · character-specific pins · available in parties and raids · inherits the active group-frame appearance and click-cast behavior."]="Расположение для всего профиля · закрепления для персонажа · доступно в группах и рейдах · наследует вид и клики-заклинания активных групповых рамок."
L["Waiting — enable Party frames first."]="Ожидание — сначала включите рамки группы."; L["Waiting — none of your saved players are in the current group."]="Ожидание — сохранённых игроков нет в текущей группе."; L["Ready — pin a group member or include tanks automatically."]="Готово — закрепите участника группы или включите автоматических танков."; L["Ready — join a party or raid to show Priority Frames."]="Готово — вступите в группу или рейд, чтобы показать приоритетные рамки."
L["Hover an MSUF Party, Raid, or Priority frame and press this key to pin or unpin that player."]="Наведите курсор на рамку MSUF группы, рейда или приоритета и нажмите эту клавишу, чтобы закрепить или открепить игрока."
L["No manual pins yet. While grouped, hover an MSUF Party, Raid, or Priority frame, then press your hotkey."]="Ручных закреплений пока нет. В группе наведите курсор на рамку MSUF группы, рейда или приоритета и нажмите назначенную клавишу."
L["Use the hover hotkey above to add or remove players."]="Используйте клавишу при наведении, чтобы добавлять или удалять игроков."; L["Saved · not grouped"]="Сохранён · вы не в группе"; L["Saved · not in current group"]="Сохранён · не в текущей группе"; L["Saved · Party frames disabled"]="Сохранён · рамки группы выключены"
L["Attach the strip to the active Party, Raid, or Mythic Raid container, or choose Free position and place it with Edit Mode."]="Прикрепите полосу к активному контейнеру группы, рейда или эпохального рейда либо выберите свободную позицию и разместите её в режиме редактирования."
L["Right of group frames"]="Справа от групповых рамок"; L["Left of group frames"]="Слева от групповых рамок"; L["Above group frames"]="Над групповыми рамками"; L["Below group frames"]="Под групповыми рамками"; L["The strip follows the active Party, Raid, or Mythic Raid container automatically."]="Полоса автоматически следует за активным контейнером группы, рейда или эпохального рейда."
L["In party"]="В группе"; L["In raid"]="В рейде"; L["Not grouped"]="Не в группе"
L["Priority Frames keep automatic tanks and manually pinned group members in a stable extra strip. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. The matching base group frames must be enabled. Open Group Frames > Priority to choose who appears, set a hover hotkey, and place the strip."]="Приоритетные рамки помещают автоматических танков и вручную закреплённых участников в постоянную дополнительную полосу. В группе они наследуют рамки группы, а в рейде — активные рамки рейда или эпохального рейда. Соответствующие базовые рамки должны быть включены. Откройте Групповые рамки > Приоритет, чтобы выбрать игроков, клавишу и позицию."
