L["Custom Aura tracking on Unitframes"] = "Пользовательское отслеживание ауры на Unitframes"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, then whitelist exact buff or debuff SpellIDs."] = "Создайте до трех пользовательских дорожек для каждого кадра: «Игрок», «Цель», «Фокус» и «Босс», а затем внесите в белый список точные SpellID для усиления или ослабления."
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "Ваши кадры MSUF могут действовать как сфокусированные трекеры в стиле WeakAura со значками, таймерами, полосами продолжительности и полнокадровыми эффектами оттенка, границы, свечения или пульсации."
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "три трекера Custom Aura для каждого поддерживаемого Unitframe, точные белые списки заклинаний и полнокадровые эффекты"
L["Build a Custom tracker"] = "Создайте собственный трекер"
L["Auras3: a full Aura menu rework"] = "Auras3: полная переработка меню Ауры."
L["The 5.71 Auras2 page has been rebuilt as Auras3, with separate Unitframe and Group workspaces plus Buff, Debuff and Custom lanes."] = "Страница Auras2 версии 5.71 была переработана в Auras3 с отдельными рабочими пространствами Unitframe и Group, а также полосами Buff, Debuff и Custom."
L["Each lane gets its own live preview, layout, growth, sorting, filters, blacklist or whitelist, cooldown text, swipe, stacks and duration bars."] = "Каждая полоса имеет собственный предварительный просмотр, макет, рост, сортировку, фильтры, черный или белый список, текст восстановления, пролистывание, стеки и шкалы длительности."
L["the rebuilt Auras3 workspace, lane-specific previews, layouts, sorting, filters and styling"] = "переработанное рабочее пространство Auras3, предварительный просмотр для каждой дорожки, макеты, сортировка, фильтры и стили."
L["Explore the Aura rework"] = "Изучите переработку Ауры"
L["Adaptive Party and Raid layouts"] = "Адаптивные макеты групп и рейдов"
L["Group frames gained smarter layouts, stronger status handling, range behavior and clearer health feedback."] = "Групповые рамки получили более продуманную компоновку, улучшенную обработку статуса, поведение диапазона и более четкую обратную связь о состоянии."
L["You can make one group setup adapt more cleanly between party, raid and encounter needs."] = "Вы можете сделать так, чтобы одна группа более четко адаптировалась к потребностям группы, рейда и столкновения."
L["adaptive group layouts, range behavior and group status controls"] = "адаптивные макеты групп, управление диапазоном и статусом группы"
L["Open Group Layout"] = "Открытый макет группы"
L["New health values and text formats"] = "Новые значения здоровья и текстовые форматы"
L["Health text can show abbreviated or full values with more consistent formatting across unit and group frames."] = "В тексте состояния могут отображаться сокращенные или полные значения с более единообразным форматированием в рамках единиц и групп."
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "Вы можете выбрать компактную читаемость или точные цифры, не отказываясь от уже используемого макета."
L["the new health abbreviations, full values and text-format options"] = "новые сокращения, полные значения и параметры текстового формата."
L["Review Group Bars"] = "Обзор групповых баров"
L["More flexible class resources"] = "Более гибкие ресурсы классов"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "Ресурсы классов получили отдельные макеты, дополнительные формы и более точные цвета для каждого слота и полного состояния."
L["You can move class information where your eyes already are and make important states easier to read."] = "Вы можете переместить информацию о классе туда, где уже находятся ваши глаза, и облегчить чтение важных состояний."
L["detached class resources, new shapes and per-state colors"] = "ресурсы отдельных классов, новые формы и цвета для каждого состояния."
L["Configure Class Resources"] = "Настройка ресурсов класса"
L["Cast target text"] = "Трансляция целевого текста"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "На панелях применения цели, фокуса и босса теперь можно указать, на кого нацелено текущее заклинание, с помощью специального стиля текста."
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "Вы можете определить место назначения важного применения, не отвлекая внимание от панели применения."
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "имена каст-целей и стиль их текста в кадрах Target, Focus и Boss"
