L["Skipping this personal step uses neutral guidance and leaves navigation, Search, autosave, Undo/Redo and page reset unexplained."] = "Пропуск этого личного шага использует нейтральное руководство и оставляет необъяснимыми навигацию, поиск, автосохранение, отмену /Redo и сброс страницы."
L["Skipping frame placement leaves whole-frame movement, snapping, nudging and safe exit behavior unexplained."] = "Пропуск размещения кадров оставляет необъяснимыми движения всего кадра, щелчки, подталкивания и поведение безопасного выхода."
L["Skipping the Player frame leaves its layout, text, indicators and aura options unreviewed."] = "При пропуске кадра игрока его макет, текст, индикаторы и параметры ауры остаются непроверенными."
L["Skipping the Target frame leaves its layout, text, indicators and aura options unreviewed."] = "При пропуске целевого кадра его макет, текст, индикаторы и параметры ауры остаются непроверенными."
L["Skipping the Focus frame leaves its layout, text, indicators and aura options unreviewed."] = "При пропуске кадра фокусировки его макет, текст, индикаторы и параметры ауры остаются непроверенными."
L["Skipping the Pet frame leaves its layout, text, indicators and aura options unreviewed."] = "При пропуске кадра «Питомец» его макет, текст, индикаторы и параметры ауры остаются непросмотренными."
L["Skipping Target of target leaves its layout, text and visibility options unreviewed."] = "Пропуск целевой цели оставляет ее макет, текст и параметры видимости непроверенными."
L["Skipping Focus target leaves its layout, text and visibility options unreviewed."] = "При пропуске цели Focus ее параметры макета, текста и видимости остаются непроверенными."
L["Skipping Boss frames leaves their shared layout, text, indicators and aura options unreviewed."] = "При пропуске кадров Босса их общий макет, текст, индикаторы и параметры ауры остаются непроверенными."
L["Skipping group layout leaves frame size, growth, sorting, scaling and anchoring unreviewed."] = "Пропуск макета группы оставляет без внимания размер кадра, рост, сортировку, масштабирование и привязку."
L["Skipping group bars leaves health, power, text, range and dispel presentation unreviewed."] = "При пропуске групповых полосок здоровье, сила, текст, дальность и рассеивание остаются без внимания."
L["Skipping group auras leaves group buff, debuff and spell-indicator behavior unreviewed."] = "Пропуск групповых аур оставляет без внимания групповые баффы, дебаффы и поведение индикаторов заклинаний."
L["Skipping Bars leaves global textures, absorbs, outlines, highlights and power behavior unreviewed."] = "Пропуск полос оставляет без внимания глобальные текстуры, поглощения, контуры, блики и поведение мощности."
L["Skipping Cast Bars leaves cast appearance, text, empowered casts and interrupt cues unreviewed."] = "Пропуск полосок каста оставляет без внимания внешний вид каста, текст, усиленные касты и сигналы прерывания."
L["Skipping Colors leaves frame, power, aura, class, text and castbar colors unreviewed."] = "Пропуск цветов оставляет цвета рамки, силы, ауры, класса, текста и панели каста непересмотренными."
L["Skipping Fonts leaves the global font, text styling, colors and name shortening unreviewed."] = "Пропуск шрифтов оставляет без внимания глобальный шрифт, стиль текста, цвета и сокращение имени."
L["Skipping Aura styling leaves buff/debuff size, cooldown, stacks, duration bars and ordering unreviewed."] = "Если пропустить стиль ауры, размер buff/debuff, время восстановления, стаки, шкалы длительности и порядок не будут пересмотрены."
L["Skipping Miscellaneous leaves language, menu behavior, startup, tooltips and Blizzard-frame integration unreviewed."] = "Пропуск «Разного» оставляет без внимания язык, поведение меню, запуск, всплывающие подсказки и интеграцию с фреймами Blizzard."
L["Skipping Class Resources leaves class layout, behavior, style, visibility and alternative power displays unreviewed."] = "Пропуск ресурсов класса оставляет без внимания макет класса, поведение, стиль, видимость и альтернативные возможности отображения."
L["Skipping Gameplay leaves combat timers, state behavior, class toggles and the combat crosshair unreviewed."] = "Пропуск игрового процесса оставляет без внимания таймеры боя, поведение состояний, переключение классов и боевое прицел."
L["Skipping Profiles leaves profile management, specialization assignment and export/import backup unreviewed."] = "Пропуск профилей оставляет без внимания управление профилями, назначение специализаций и резервное копирование экспорта /import."
L["Skipping the final review hides the summary, but does not change any setting."] = "Пропуск финальной проверки скрывает сводку, но не меняет никаких настроек."
