L["On previews every enabled spell for this spec. Off previews only the selected spell."] = "На превью каждого активированного заклинания для этой специализации. Выкл. — предварительный просмотр только выбранного заклинания."
L["Opacity remains beside the setting when that element supports it."] = "Непрозрачность остается рядом с настройкой, если этот элемент поддерживает ее."
L["Open Aura Style"] = "Открытый стиль ауры"
L["Open Bars"] = "Открытые бары"
L["Open Colors > Bar Gradient Colors for separate Health and Power gradient colors in the selected Bars scope."] = "Откройте «Цвета» > «Цвета градиента полос», чтобы получить отдельные цвета градиента здоровья и силы в выбранной области «Полоски»."
L["Open Colors > Group Frame Colors for shared Party, Raid and Mythic Raid colors."] = "Откройте «Цвета» > «Цвета групповой рамки», чтобы получить общие цвета группы, рейда и мифического рейда."
L["Open Edit Mode and move Party Frames"] = "Откройте режим редактирования и переместите рамки вечеринки."
L["Open Group Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "Откройте «Групповые рамки» > «Ауры» для фильтров усиления/дебаффа, списков, видимости и макета. Для текста, времени восстановления, стаков и шкалы продолжительности используйте «Внешний вид» > «Ауры» и выберите область действия «Группа» или «Рейд»."
L["Open Group Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Global Style > Bars > Absorb Display."] = "Откройте «Групповые рамки» > «Макет». «Текст», «Панель ресурсов» и «Затухание диапазона» расположены рядом с «Основами кадра» и «Прозрачность». Наложение «Рассеивание» и полоса дебаффа находятся на странице «Наложение рассеивания». Прогноз исцеления осуществляется в разделе «Глобальный стиль» > «Полоски» > «Поглощение дисплея»."
L["Open it and choose a different value."] = "Откройте его и выберите другое значение."
L["Open the affected UnitFrame > Auras > Debuffs and enable the native Dispellable rule. For Party/Raid use Group Frames > Auras > Debuffs."] = "Откройте затронутый UnitFrame > Ауры > Ослабления и включите встроенное правило Dispelable. Для вечеринки/рейда используйте «Групповые рамки» > «Ауры» > «Ослабления»."
L["Open the affected UnitFrame > Auras > Debuffs and use its frame-specific SpellID blacklist. Group exclusions live directly in Group Frames > Auras > Debuffs."] = "Откройте затронутый UnitFrame > Ауры > Ослабления и используйте черный список SpellID для конкретного фрейма. Групповые исключения находятся непосредственно в разделе «Групповые рамки» > «Ауры» > «Ослабления»."
L["Open the affected UnitFrame > Auras and choose Buffs or Debuffs. Check its frame-specific Blizzard filters, blacklist, enabled state, and icon cap. For Party/Raid use Group Frames > Auras."] = "Откройте затронутый UnitFrame > Ауры и выберите «Усиления» или «Ослабления». Проверьте фильтры Blizzard для конкретных фреймов, черный список, включенное состояние и крышку значка. Для вечеринки/рейда используйте «Групповые рамки» > «Ауры»."
L["Open the affected UnitFrame > Auras for visibility, layout, filters, and blacklists. Use Appearance > Auras for scope-aware cooldown, stack, duration-bar, and icon styling."] = "Откройте затронутый UnitFrame > Auras, чтобы просмотреть видимость, макет, фильтры и черные списки. Используйте «Внешний вид» > «Ауры», чтобы настроить время восстановления, стек, шкалу продолжительности и стиль значков с учетом прицела."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own Blizzard filters and blacklists; Custom 1-3 contains its own whitelist. There is no separate Filter tab."] = "Откройте рамку и разверните Ауры. Баффы и дебаффы содержат собственные фильтры и черные списки Blizzard; Custom 1-3 содержит собственный белый список. Отдельной вкладки «Фильтр» нет."
L["Open the matching color section below."] = "Откройте раздел подходящего цвета ниже."
L["Opens Buff styling for this frame. Spell choice, placement, size, layer, and frame highlight stay unique to this indicator."] = "Открывает стиль Buff для этого кадра. Выбор заклинания, размещение, размер, слой и подсветка кадра остаются уникальными для этого индикатора."
L["Opens: Group Frames > Auras"] = "Открывает: Групповые рамки > Ауры."
L["Opens: Group Frames > Status & Indicators"] = "Открывается: Групповые рамки > Статус и индикаторы."
L["Opens: Target > Auras"] = "Открывается: Цель > Ауры."
L["Original"] = "Оригинал"
L["Out of range"] = "Вне диапазона"
L["Outline color"] = "Цвет контура"
L["Over-absorb overlay"] = "Чрезмерно впитывающая накладка"
L["PART 1 - Build Player once, then copy the finished setup to the other Unitframes."] = "ЧАСТЬ 1. Создайте Player один раз, а затем скопируйте готовые настройки в другие Unitframes."
