L["Thresholds choose when Warning and Urgent replace the Safe timer color."] = "Пороговые значения определяют, когда «Предупреждение» и «Срочно» заменяют безопасный цвет таймера."
L["Timer colors are shared by live unit/group auras and every preview."] = "Цвета таймера общие для аур единиц/группы в реальном времени и всех предпросмотров."
L["Turns off MSUF frames for this scope and forces Blizzard group frames visible. Use this only when Blizzard's frames do not appear with the normal WoW settings option."] = "Отключает рамки MSUF для этой области и принудительно показывает рамки группы Blizzard. Используйте только если обычная настройка WoW их не показывает."
L["Turns off MSUF frames for this scope and returns control to WoW. Blizzard's own Party or Raid Frame settings decide when its frames appear."] = "Отключает рамки MSUF для этой области и возвращает управление WoW. Настройки рамок группы или рейда Blizzard определяют, когда они появляются."
L["Use custom settings for this frame"] = "Использовать пользовательские настройки для этой рамки"
L["Use player's class color for Pet Frame"] = "Использовать цвет класса игрока для рамки питомца"
L["Player Class Color"] = "Цвет класса игрока"
L["Colors the Pet health bar with your class color while its Health Color Scheme is Class / Reaction."] = "Окрашивает полосу здоровья питомца в цвет вашего класса, когда схема цвета здоровья установлена на «Класс/реакция»."
L["Uses MSUF's custom group frames for the selected Party, Raid, or Mythic Raid scope. The other scopes remain independent."] = "Использует рамки группы MSUF для выбранной области группы, рейда или эпохального рейда. Остальные области остаются независимыми."
