--- Fill Direction and Power bar textures (6.0 Beta 26)
L["Power Bar Texture"] = "Текстура полосы ресурса"
L["Power Background Texture"] = "Текстура фона ресурса"
L["Power Texture"] = "Текстура ресурса"
L["Power Background"] = "Фон ресурса"
L["Fill Direction"] = "Направление заполнения"
L["Left to Right"] = "Слева направо"
L["Right to Left"] = "Справа налево"
L["Bottom to Top"] = "Снизу вверх"
L["Top to Bottom"] = "Сверху вниз"
L["Art for every unit's power bar. Leave on Use bar texture to keep the shared bar art. Each unit page can override this, and the Class Resources detached power texture still wins for a detached Player bar."] = "Оформление полосы ресурса каждой единицы. Оставьте «Использовать текстуру полосы», чтобы сохранить общее оформление. Каждая страница юнита может переопределить это, а отдельная текстура ресурса из Ресурсов класса по-прежнему имеет приоритет для отсоединённой полосы игрока."
L["Art for this frame's power bar, detached or not. Leave on the global option to follow the shared Bars power texture."] = "Оформление полосы ресурса этой рамки, отсоединённой или нет. Оставьте глобальный вариант, чтобы следовать общей текстуре ресурса из настроек полос."
L["Axis and direction the Health and Power bars fill. Vertical options fill bottom-to-top or top-to-bottom; combines with Smooth fill."] = "Ось и направление заполнения полос здоровья и ресурса. Вертикальные варианты заполняют снизу вверх или сверху вниз и сочетаются с плавным заполнением."
L["Background art behind every unit's power bar. Overridable per unit on the unit page."] = "Фоновое оформление за полосой ресурса каждой единицы. Можно переопределить для каждого юнита на его странице."
L["Background art behind this frame's power bar."] = "Фоновое оформление за полосой ресурса этой рамки."

